// Headless CDP test for DISC copy
import { readFileSync } from "node:fs";

const PORT = 9333;
const PAGE = "file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-rtf9o54n/run/index.html";

async function getJSON(path) {
  const r = await fetch(`http://127.0.0.1:${PORT}${path}`);
  return r.json();
}

class CDP {
  constructor(wsUrl) { this.ws = null; this.wsUrl = wsUrl; this.id = 0; this.pending = new Map(); this.events = []; }
  connect() {
    return new Promise((res, rej) => {
      this.ws = new WebSocket(this.wsUrl);
      this.ws.onopen = () => res();
      this.ws.onerror = (e) => rej(new Error("ws error"));
      this.ws.onmessage = (m) => {
        const msg = JSON.parse(m.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { res, rej } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
        } else if (msg.method) {
          this.events.push(msg);
        }
      };
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((res, rej) => {
      this.pending.set(id, { res, rej });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.has(id)) { this.pending.delete(id); rej(new Error("timeout " + method)); } }, 15000);
    });
  }
  async eval(expr) {
    const r = await this.send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error("page exception: " + JSON.stringify(r.exceptionDetails.exception?.description || r.exceptionDetails.text));
    return r.result.value;
  }
  close() { this.ws.close(); }
}

let failures = 0;
function check(name, cond, extra = "") {
  console.log((cond ? "PASS" : "FAIL") + "  " + name + (extra ? "  [" + extra + "]" : ""));
  if (!cond) failures++;
}

// 1) start chrome
const proc = spawn();
function spawn() {
  const { spawn: sp } = require_sp;
  return sp("google-chrome", [
    "--headless=new", `--remote-debugging-port=${PORT}`, "--no-sandbox", "--disable-gpu",
    "--user-data-dir=/tmp/disc-chrome-prof", "about:blank"
  ], { stdio: "ignore" });
}
const require_sp = { spawn: (await import("node:child_process")).spawn };

await new Promise(r => setTimeout(r, 1500));

const targets = await getJSON("/json/list");
let target = targets.find(t => t.type === "page");
if (!target) {
  const created = await (await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: "PUT" })).json();
  target = created;
}

const cdp = new CDP(target.webSocketDebuggerUrl);
await cdp.connect();
await cdp.send("Page.enable");
await cdp.send("Runtime.enable");

const nav = cdp.send("Page.navigate", { url: PAGE });
await new Promise(r => setTimeout(r, 800));
await nav;

const logs = [];
cdp.events.push();
// capture console errors
const pageConsole = [];

// 2) structural checks
const S = await cdp.eval(`(() => {
  const tabs = document.querySelectorAll("#tabs .tab");
  const panes = document.querySelectorAll("#panes .pane");
  const cards = document.querySelectorAll(".qcard");
  const items = document.querySelectorAll(".disc-item");
  const first = Array.from(document.querySelectorAll("#panes .disc-list")).slice(0,3).map(ul => Array.from(ul.children).map(li => [li.dataset.type, li.textContent.trim()]));
  return {
    tabs: tabs.length,
    tabNames: Array.from(tabs).map(t => t.textContent),
    panes: panes.length,
    cards: cards.length,
    items: items.length,
    step0Visible: !panes[0].hidden,
    othersHidden: Array.from(panes.slice(1)).every(p => p.hidden),
    prevDisabled: document.getElementById("btnPrev").disabled,
    nextHidden: document.getElementById("btnNext").hidden === false,
    finishHidden: document.getElementById("btnFinish").hidden,
    progress: document.getElementById("progressBar").style.width,
    first
  };
})()`);

check("8 tabs", S.tabs === 8, String(S.tabs));
check("tab names original", JSON.stringify(S.tabNames) === JSON.stringify(["Первый","Второй","Третий","Четвертый","Пятый","Шестой","Седьмой","Восьмой"]), S.tabNames.join("|"));
check("8 panes", S.panes === 8, String(S.panes));
check("24 cards", S.cards === 24, String(S.cards));
check("96 items", S.items === 96, String(S.items));
check("step 0 active only", S.step0Visible && S.othersHidden);
check("Назад disabled at step 0", S.prevDisabled === true);
check("Далее visible, Завершить hidden", S.nextHidden === true && S.finishHidden === true);
check("progress 12.5%", S.progress === "12.5%", S.progress);
check("first card word exact (Latin c)", S.first[0][0][1] === "Экспресcивный", JSON.stringify([...S.first[0][0][1].codePointAt ? [] : S.first[0][0][1]].map(c => c.codePointAt(0))));

// words multiset check vs original
const wordsPage = await cdp.eval(`JSON.stringify(Array.from(document.querySelectorAll(".disc-item")).map(li => [li.dataset.type, li.textContent.trim()]))`);
const origWords = JSON.stringify((await import("node:fs")).readFileSync ? undefined : undefined);
let origWordList;
try { origWordList = JSON.parse(readFileSync("/tmp/disc_words.json", "utf8")); } catch { /* created below */ }
const pageWords = JSON.parse(wordsPage);
pageWords.sort((a,b) => (a[0]+a[1]).localeCompare(b[0]+b[1], "ru"));
const origSorted = origWordList ? [...origWordList].sort((a,b) => (a[0]+a[1]).localeCompare(b[0]+b[1], "ru")) : null;
check("96 (type,word) pairs match original", origSorted !== null && JSON.stringify(pageWords) === JSON.stringify(origSorted));

// 3) drag simulation: for each list, drag the LAST li to the TOP (mouse events)
const drag = await cdp.eval(`(() => {
  const UL = document.querySelectorAll(".before" || ".disc-list");
  function fire(el, type, opts) {
    el.dispatchEvent(new PointerEvent(type, Object.assign({ bubbles: true, cancelable: true, view: window, pointerType: "mouse", pointerId: 1, isPrimary: true, button: 0, buttons: 1 }, opts)));
  }
  const results = [];
  const uls = Array.from(document.querySelectorAll(".disc-list"));
  for (const ul of uls) {
    const lis = Array.from(ul.children);
    const last = lis[lis.length - 1];
    const first = lis[0];
    const r = first.getBoundingClientRect();
    const rr = last.getBoundingClientRect();
    fire(last, "pointerdown", { clientX: rr.x + rr.width / 2, clientY: rr.y + rr.height / 2 });
    // move above the first item, in steps
    const steps = 4;
    for (let k = 1; k <= steps; k++) {
      const y = rr.y + (r.y + r.height * 0.3 - rr.y) * (k / steps);
      fire(window, "pointermove", { clientX: rr.x + rr.width / 2, clientY: y });
    }
    // ensure final position above first item
    fire(window, "pointermove", { clientX: rr.x + rr.width / 2, clientY: r.y + r.height * 0.2 });
    fire(window, "pointerup", { clientX: rr.x + rr.width / 2, clientY: r.y + r.height * 0.2 });
    const now = Array.from(ul.children).map(li => li.textContent.trim());
    results.push({ list: uls.indexOf(ul), top: now[0], bottom: now[3] });
  }
  return JSON.stringify(results);
})()`);
const dragRes = JSON.parse(drag);
let allTopChanged = true;
for (const row of dragRes) {
  const origTop = JSON.parse(readFileSync("/tmp/disc_data.json", "utf8"))[row.list][0][1];
  const origLast = JSON.parse(readFileSync("/tmp/disc_data.json", "utf8"))[row.list][3][1];
  if (row.top !== origLast || row.top === origTop) allTopChanged = false;
}
check("drag moved last item to top in all 24 lists", allTopChanged, JSON.stringify(dragRes.slice(0, 3)));

// 4) navigate to last step
await cdp.eval(`document.querySelector('.tab[data-step-btn="7"]').click()`);
await new Promise(r => setTimeout(r, 200));
const T = await cdp.eval(`(() => ({
  pane7: !document.querySelector('.pane[data-step-pane="7"]').hidden,
  prevDisabled: document.getElementById("btnPrev").disabled,
  nextHidden: document.getElementById("btnNext").hidden,
  finishHidden: document.getElementById("btnFinish").hidden,
  progress: document.getElementById("progressBar").style.width,
  activeTab: document.querySelector('.tab.is-active').textContent
}))()`);
check("jump to step 8 via tab", T.pane7 && T.activeTab === "Восьмой");
check("Назад enabled at last step", T.prevDisabled === false);
check("Далее hidden at last step", T.nextHidden === true);
check("Завершить тест visible at last step", T.finishHidden === false);
check("progress 100%", T.progress === "100%", T.progress);

// 5) back button
await cdp.eval(`document.getElementById("btnPrev").click()`);
await new Promise(r => setTimeout(r, 200));
const B = await cdp.eval(`(() => ({
  pane6: !document.querySelector('.pane[data-step-pane="6"]').hidden,
  nextHidden: document.getElementById("btnNext").hidden,
  finishHidden: document.getElementById("btnFinish").hidden
}))()`);
check("Назад returns to step 7", B.pane6);
check("Далее visible / Завершить hidden again", B.nextHidden === false && B.finishHidden === true);

// back to last step and finish
await cdp.eval(`document.querySelector('.tab[data-step-btn="7"]').click()`);
await new Promise(r => setTimeout(r, 200));
await cdp.eval(`document.getElementById("btnFinish").click()`);
await new Promise(r => setTimeout(r, 300));

const R = await cdp.eval(`(() => ({
  testHidden: document.getElementById("testCard").hidden,
  resultVisible: !document.getElementById("resultCard").hidden,
  score: document.getElementById("resultScore").textContent,
  types: Array.from(document.querySelectorAll("#resultTypes .type")).map(t => t.dataset.type),
  vals: Array.from(document.querySelectorAll("#resultTypes .val")).map(v => v.textContent)
}))()`);
check("result view replaces test view", R.testHidden && R.resultVisible);
check("score format 'D:-3, I:1, S:3, C:-1'", R.score === "D:-3, I:1, S:3, C:-1", R.score);
check("type cards d,i,s,c with values", JSON.stringify(R.types) === '["d","i","s","c"]' && JSON.stringify(R.vals) === '["-3","1","3","-1"]', JSON.stringify(R.vals));

// 6) restart resets order and returns to step 0
await cdp.eval(`document.getElementById("btnRestart").click()`);
await new Promise(r => setTimeout(r, 300));
const RS = await cdp.eval(`(() => {
  const ul = document.querySelector(".disc-list");
  const firstWord = ul.children[0].textContent.trim();
  return {
    testVisible: !document.getElementById("testCard").hidden,
    resultHidden: document.getElementById("resultCard").hidden,
    firstWord,
    progress: document.getElementById("progressBar").style.width
  };
})()`);
check("restart: test back, result hidden", RS.testVisible && RS.resultHidden);
check("restart: order reset to original", RS.firstWord === "Экспресcивный", RS.firstWord);
check("restart: step 0", RS.progress === "12.5%");

// 7) no uncaught page errors: check Runtime.exceptionThrown events
const excEvents = cdp.events.filter(e => e.method === "Runtime.exceptionThrown");
check("no uncaught page exceptions", excEvents.length === 0, JSON.stringify(excEvents.slice(0,2)));
const consoleEvents = cdp.events.filter(e => e.method === "Runtime.consoleAPICalled" && e.params.type === "error");
check("no console errors", consoleEvents.length === 0, JSON.stringify(consoleEvents.slice(0,2)));

cdp.close();
proc.kill();
console.log(failures === 0 ? "\nALL CHECKS PASSED" : `\n${failures} CHECKS FAILED`);
process.exit(failures === 0 ? 0 : 1);

